def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {n: set() for n in nodes}
    indegree = {n: 0 for n in nodes}

    for edge in edges:
        src, dst = edge
        if src == dst:
            raise ValueError("self-loop detected: cycle")
        if dst not in adj[src]:
            adj[src].add(dst)
            indegree[dst] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit πρέπει να είναι θετικό")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("κάθε βάρος πρέπει να είναι θετικό και <= limit")
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current and current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import math


def retry_delay(attempt, base, cap):
    """Return float(min(cap, base * 2**attempt)).

    - attempt: nonnegative integer
    - base, cap: finite nonnegative numbers
    """
    if attempt < 0:
        raise ValueError("attempt must be a nonnegative integer")
    if base < 0:
        raise ValueError("base must be nonnegative")
    if cap < 0:
        raise ValueError("cap must be nonnegative")

    # base == 0 -> product is 0; cap == 0 -> min is 0 (product is nonnegative).
    if base == 0.0 or cap == 0.0:
        return 0.0

    # We want min(cap, base * 2**attempt).
    # base * 2**attempt >= cap  <=>  attempt >= log2(cap / base).
    # Compare via logarithms to avoid ever building the huge 2**attempt value.
    if attempt >= math.log2(cap / base):
        return float(cap)

    # Here base * 2**attempt < cap <= ~1.8e308, so attempt is bounded (~< 2096)
    # and the result is finite. ldexp computes base * 2**attempt directly from
    # the float's exponent, so it never constructs a huge integer and cannot
    # overflow for inputs that land in this branch.
    return float(math.ldexp(base, attempt))
